import java.util.HashSet;
import java.util.Set;

class Solution {
    public int repeatedNTimes(int[] nums) {
        Set<Integer> seen = new HashSet<>();
        for (int value : nums) {
            if (!seen.add(value)) {
                return value;
            }
        }
        return -1;
    }
}

class Solution {
    public int repeatedNTimes(int[] nums) {
        for (int i = 0; i < nums.length; i++) {
            for (int distance = 1; distance <= 3 && i + distance < nums.length; distance++) {
                if (nums[i] == nums[i + distance]) {
                    return nums[i];
                }
            }
        }
        return -1;
    }
}

class Solution {
    public int repeatedNTimes(int[] nums) {
        int[] count = new int[10001];
        for (int value : nums) {
            count[value]++;
            if (count[value] == 2) {
                return value;
            }
        }
        return -1;
    }
}

import java.util.Arrays;

class Solution {
    public int repeatedNTimes(int[] nums) {
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        for (int i = 1; i < sorted.length; i++) {
            if (sorted[i] == sorted[i - 1]) {
                return sorted[i];
            }
        }
        return -1;
    }
}

class Solution {
    public int repeatedNTimes(int[] nums) {
        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length; j++) {
                if (nums[i] == nums[j]) {
                    return nums[i];
                }
            }
        }
        return -1;
    }
}
